#include "sherpa-onnx/csrc/speaker-embedding-extractor.h"
#include "sherpa-onnx/csrc/online-stream.h"
#include "sherpa-onnx/csrc/features.h"
std::vector<float> sdk_compile_only(sherpa_onnx::SpeakerEmbeddingExtractor const& extractor, const float* pcm, int n) {
  sherpa_onnx::FeatureExtractorConfig config;
  config.sampling_rate = 16000;
  config.feature_dim = 80;
  config.window_type = "hamming";
  config.snip_edges = true;
  config.high_freq = 0;
  config.normalize_samples = false;
  sherpa_onnx::OnlineStream stream(config);
  stream.AcceptWaveform(16000, pcm, n);
  stream.InputFinished();
  if (!extractor.IsReady(&stream)) return {};
  return extractor.Compute(&stream);
}
int main() { return 0; }
